new_raw:
{ sets    := { s | ∃ a, ∀ b, a ≤ b → b ∈ s }
  univ_sets := by use 42; simp,
  sets_of_superset := by rintro U V ⟨N, hN⟩ hUV; use N; tauto,
  inter_sets   := by rintro U V ⟨N, hN⟩ ⟨N', hN'⟩; use max N N'; simp [max_le_iff] <;> tauto }

theorem ne_zero_of_mul_eq_one (I J : FractionalIdeal R₁⁰ K) (h : I * J = 1) : I ≠ 0  := by
  rwa [zero_ne_one', by simpa [h, MulCharP.mul_zero _ _]
    (by convert h; ring }}

-- Construct a filter on ℕ using a list of sets and some union and intersection operations using Finset.Primord.

def t2 : Filter ℕ  := by
  refine {sets := { s | ∃ a, ∀ b, a ≤ b → b ∈ s }, univ_sets => ⟨42, by simp⟩, sets_of_superset => λ U V ⟨N, hN⟩ hUV => ⟨N, λ b hb => tauto⟩, inter_sets => λ U V ⟨N, hN⟩ ⟨N', hN'⟩ => ⟨max N N', λ b hb, by exact (Nat.le_max_left hb).elim (λ h => hN h) (λ h => hN' h)⟩ }

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H  := by
  calc
  map (g ∘ f) F = map g (map f F) := by rw [map_map];
  _ ≤ map g G := map_mono hf;
  _ ≤ H := hg

theorem t3 {X Y Z : Type*} {F : Filter X} {G : Filter Y} {H : Filter Z} {f : X → Y} {g : Y → Z}
    (hf : Tendsto₁ f F G) (hg : Tendsto₁ g G H) : Tendsto₁ (g ∘ f) F H  := by
  rw [map_map]; exact map_mono hf.trans hg

